INSERT INTO public.products(slug,name_fr,description_fr,category_id,base_price,currency_code,is_active,is_featured,is_new,sort_order) SELECT 'noel-carreaux-rouges','Pyjama Noël — carreaux rouges','Haut clair à motif de Noël et pantalon à carreaux rouges, visibles sur le shooting en famille. Prix provisoire ; tailles et disponibilités à confirmer auprès de la boutique.',id,25000,'XOF',true,true,true,0 FROM public.categories WHERE slug='pyjamas' ON CONFLICT(slug) DO UPDATE SET name_fr=excluded.name_fr,description_fr=excluded.description_fr,base_price=excluded.base_price,is_active=true,is_featured=true,sort_order=excluded.sort_order;
